import AppKit
import CoreGraphics

let pointPerMM: CGFloat = 72 / 25.4
let ink = NSColor(white: 0.10, alpha: 1)
let gray = NSColor(white: 0.29, alpha: 1)
let rule = NSColor(white: 0.55, alpha: 1)
let tint = NSColor(white: 0.95, alpha: 1)
let white = NSColor.white

struct Canvas {
    let context: CGContext
    let width: CGFloat
    let height: CGFloat

    func rect(_ x: CGFloat, _ y: CGFloat, _ w: CGFloat, _ h: CGFloat) -> CGRect {
        CGRect(x: x * pointPerMM, y: (height - y - h) * pointPerMM,
               width: w * pointPerMM, height: h * pointPerMM)
    }

    func box(_ x: CGFloat, _ y: CGFloat, _ w: CGFloat, _ h: CGFloat,
             fill: NSColor? = nil, stroke: NSColor? = nil, weight: CGFloat = 0.55) {
        let area = rect(x, y, w, h)
        if let fill {
            context.setFillColor(fill.cgColor)
            context.fill(area)
        }
        if let stroke {
            context.setStrokeColor(stroke.cgColor)
            context.setLineWidth(weight)
            context.stroke(area)
        }
    }

    func line(_ x: CGFloat, _ y: CGFloat, _ endX: CGFloat, _ endY: CGFloat,
              color: NSColor = rule, weight: CGFloat = 0.55) {
        context.setStrokeColor(color.cgColor)
        context.setLineWidth(weight)
        context.move(to: CGPoint(x: x * pointPerMM, y: (height - y) * pointPerMM))
        context.addLine(to: CGPoint(x: endX * pointPerMM, y: (height - endY) * pointPerMM))
        context.strokePath()
    }

    func label(_ text: String, _ x: CGFloat, _ y: CGFloat, _ size: CGFloat,
               bold: Bool = false, color: NSColor = ink, width: CGFloat? = nil,
               alignment: NSTextAlignment = .left) {
        let font = NSFont(name: bold ? \"HelveticaNeue-Bold\" : \"HelveticaNeue\", size: size)"'!
        let attributed = NSAttributedString(string: text, attributes: [
            .font: font,
            .foregroundColor: color
        ])
        let measured = attributed.size()
        var left = x * pointPerMM
        if let width {
            precondition(measured.width <= width * pointPerMM, "Text exceeds its space: '"\\(text)\")
            let remaining = width * pointPerMM - measured.width
            if alignment == .center { left += remaining / 2 }
            if alignment == .right { left += remaining }
        }
        attributed.draw(at: CGPoint(x: left, y: (height - y) * pointPerMM - measured.height))
    }
}

func fridge(_ canvas: Canvas) {
    let cardWidth: CGFloat = 184
    let cardHeight: CGFloat = 232
    let originX = (canvas.width - cardWidth) / 2
    let originY = (canvas.height - cardHeight) / 2
    let x = originX + 8
    let y = originY
    let contentWidth: CGFloat = 168

    canvas.box(originX, originY, cardWidth, cardHeight, stroke: ink)
    canvas.label(\"Shared kitchen\", x, y + 7.5, 32, bold: true, width: contentWidth)

    let pantry = [
        (\"PERSONAL SHELVES 1–3\", \"Ask before taking.\"),
        (\"SHARED SHELF\", \"Everyone can use it.\"),
        (\"GIVE-AWAY BASKET\", \"Free to take.\")
    ]
    for (index, key) in pantry.enumerated() {
        let left = x + CGFloat(index) * 57
        canvas.box(left, y + 27, 54, 17, fill: tint)
        canvas.label(key.0, left + 3, y + 29.7, 9.6, bold: true, width: 48)
        canvas.label(key.1, left + 3, y + 35.2, 10.5, width: 48)
    }

    canvas.label(\"Next shopper\", x, y + 50, 17, bold: true)
    canvas.label(\"Circle one number   •   1 → 2 → 3 → 1\", x + 57, y + 51.8, 10.5,
                 color: gray, width: 111, alignment: .right)
    for index in 0..<3 {
        let left = x + CGFloat(index) * 57
        canvas.box(left, y + 59.5, 54, 14.5, stroke: rule)
        canvas.label(String(index + 1), left + 2, y + 62.8, 15, bold: true, width: 11, alignment: .center)
        canvas.line(left + 15, y + 70, left + 49, y + 70)
    }

    canvas.label(\"Shared staples\", x, y + 81, 17, bold: true)
    canvas.label(\"Use pencil · Keep one mark per row\", x + 62, y + 83, 10.5,
                 color: gray, width: 106, alignment: .right)
    let top = y + 90
    let headers = [\"STAPLE\", \"MARK LOW WHEN LEFT\", \"LOW\", \"BUYING\", \"REPLENISHED\"]
    let edges: [CGFloat] = [0, 24, 77, 99, 126, 168]
    let headerHeight: CGFloat = 10
    let rowHeight: CGFloat = 12.5
    let staples = [
        (\"Oil\", \"About ¼ bottle\"),
        (\"Salt\", \"About ¼ container\"),
        (\"Rice\", \"Enough for one shared meal\"),
        (\"Tea\", \"About five servings\")
    ]
    let tableHeight = headerHeight + CGFloat(staples.count) * rowHeight
    canvas.box(x, top, contentWidth, headerHeight, fill: tint)
    for column in headers.indices {
        let width = edges[column + 1] - edges[column]
        let centered = column >= 2
        canvas.label(headers[column], x + edges[column] + (centered ? 0 : 3), top + 3.1, 9.2,
                     bold: true, width: width - (centered ? 0 : 5), alignment: centered ? .center : .left)
    }
    for (index, staple) in staples.enumerated() {
        let rowTop = top + headerHeight + CGFloat(index) * rowHeight
        canvas.line(x, rowTop, x + contentWidth, rowTop)
        canvas.label(staple.0, x + 3, rowTop + 3.5, 12, bold: true, width: 19)
        canvas.label(staple.1, x + 27, rowTop + 3.8, 10.4, width: 48)
    }
    for edge in edges.dropFirst().dropLast() {
        canvas.line(x + edge, top, x + edge, top + tableHeight)
    }
    canvas.box(x, top, contentWidth, tableHeight, stroke: ink, weight: 0.7)

    canvas.label(\"How to update\", x, y + 157, 17, bold: true)
    let steps: [(String, String, String?)] = [
        (\"Low\", \"When a staple runs low, erase its old check and put a check under LOW.\", nil),
        (\"Buying\", \"The circled shopper picks one LOW item, erases its check, and writes their number\",
         \"under BUYING. Circle the number after theirs for the next turn.\"),
        (\"Replenished\", \"After putting the staple away, erase your number and check REPLENISHED.\", nil)
    ]
    let stepY: [CGFloat] = [167, 175, 188]
    for (index, step) in steps.enumerated() {
        let row = y + stepY[index]
        canvas.label(step.0, x, row, 10.4, bold: true, width: 26)
        canvas.label(step.1, x + 28, row, 10.4, width: 140)
        if let second = step.2 {
            canvas.label(second, x + 28, row + 4.8, 10.4, width: 140)
        }
    }
    canvas.label(\"If the circled shopper is already buying, go to the next free shopper in order.\",
                 x, y + 197, 10.4, width: 168)
    canvas.label(\"If all three are buying, leave the item marked LOW until someone is free.\",
                 x, y + 201.8, 10.4, width: 168)

    canvas.line(x, y + 212, x + contentWidth, y + 212)
    canvas.label(\"Set up\", x, y + 216, 10.4, bold: true, width: 26)
    canvas.label(\"Match names to shelf numbers. Circle 1. Check LOW or REPLENISHED\",
                 x + 28, y + 216, 10.4, width: 140)
    canvas.label(\"for each staple based on what’s on the shelf.\", x + 28, y + 220.8, 10.4, width: 140)
}

