func makePDF(filename: String, width: CGFloat, height: CGFloat) {
    var mediaBox = CGRect(x: 0, y: 0, width: width * pointPerMM, height: height * pointPerMM)
    let output = URL(fileURLWithPath: filename)
    let metadata = [kCGPDFContextTitle as String: \"Shared Kitchen Labels and Fridge Reference\"]
    let pdf = CGContext(output as CFURL, mediaBox: &mediaBox, metadata as CFDictionary)"'!
    for render in [fridge, labels] {
        pdf.beginPDFPage(nil)
        NSGraphicsContext.saveGraphicsState()
        NSGraphicsContext.current = NSGraphicsContext(cgContext: pdf, flipped: false)
        render(Canvas(context: pdf, width: width, height: height))
        NSGraphicsContext.restoreGraphicsState()
        pdf.endPDFPage()
    }
    pdf.closePDF()
}

